from pathlib import Path

import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import torch


# Read the three (1,1) QAT-joint checkpoints generated by
# main_optics_bit_QAT_phase_attenuation_1.1_joint_train_MNIST_A.py,
# and compare their quantized theta distributions in one figure.
SCRIPT_DIR = Path(__file__).resolve().parent

SEEDS = [42, 123, 2024]
B_THETA = 1
B_ALPHA = 1

COMBINED_OUTPUT_PATH = (
    SCRIPT_DIR
    / "Figs"
    / "mnist_qat_joint_attenu_theta_distribution_3_seeds.pdf"
)

THETA_PERIOD = 2.0 * np.pi
NUM_BINS = 80

# High-contrast, color-vision-deficiency-friendly palette commonly used in
# Nature-style scientific figures (NPG palette).
NATURE_COLORS = ["#D55E00", "#0072B2", "#009E73"]
TITLE_FONTSIZE = 15
AXIS_LABEL_FONTSIZE = 14
TICK_LABEL_FONTSIZE = 12
LEGEND_FONTSIZE = 11
ANNOTATION_FONTSIZE = 10.5


def checkpoint_path(seed):
    return SCRIPT_DIR / (
        "main_optics_bit_QAT_joint_shared_theta_bias_phase_1.1_"
        f"bt_{B_THETA}_ba_{B_ALPHA}_seed_{seed}.pt"
    )


def load_checkpoint(path):
    if not path.exists():
        raise FileNotFoundError(f"Checkpoint not found: {path.resolve()}")

    checkpoint = torch.load(path, map_location="cpu")

    if not isinstance(checkpoint, dict):
        raise TypeError(f"Checkpoint must be a dictionary: {path.resolve()}")

    if "model_state_dict" not in checkpoint:
        raise KeyError(f"Checkpoint does not contain 'model_state_dict': {path.resolve()}")

    return checkpoint


def collect_theta(state_dict):
    theta_key_fragments = [
        "path_theta10",
        "path_theta21",
        "path_theta32",
        "path_theta43",
        "bias_phase1",
        "bias_phase2",
        "bias_phase3",
    ]
    tensors = []

    for key, value in state_dict.items():
        if not torch.is_tensor(value):
            continue

        key_lower = key.lower()
        if any(fragment in key_lower for fragment in theta_key_fragments):
            tensors.append(value.detach().cpu().reshape(-1))

    if not tensors:
        raise KeyError("No path-theta or bias-phase tensors were found in model_state_dict.")

    theta = torch.cat(tensors, dim=0).numpy()
    theta = theta[np.isfinite(theta)]

    if theta.size == 0:
        raise ValueError("The matched theta tensors contain no finite values.")

    return theta


def collect_attenu(state_dict):
    attenu_key_fragments = [
        "path_a_trans10",
        "path_a_trans21",
        "path_a_trans32",
        "path_a_trans43",
    ]
    tensors = []

    for key, value in state_dict.items():
        if not torch.is_tensor(value):
            continue

        key_lower = key.lower()
        if any(fragment in key_lower for fragment in attenu_key_fragments):
            tensors.append(value.detach().cpu().reshape(-1))

    if not tensors:
        raise KeyError("No attenuation tensors were found in model_state_dict.")

    attenu = torch.cat(tensors, dim=0).numpy()
    attenu = attenu[np.isfinite(attenu)]

    if attenu.size == 0:
        raise ValueError("The matched attenuation tensors contain no finite values.")

    return attenu


def quantize_theta_uniform(theta, num_bits):
    theta_wrapped = np.mod(theta, THETA_PERIOD)
    num_levels = 2 ** int(num_bits)
    step = THETA_PERIOD / num_levels
    indices = np.round(theta_wrapped / step).astype(np.int64)
    indices = np.mod(indices, num_levels)
    return indices * step


def quantize_attenu_uniform(attenu, num_bits):
    attenu_clipped = np.clip(attenu, 0.0, 1.0)
    num_levels = 2 ** int(num_bits)
    step = 1.0 / (num_levels - 1)
    indices = np.round(attenu_clipped / step).astype(np.int64)
    indices = np.clip(indices, 0, num_levels - 1)
    return indices * step


def load_quantized_theta(seed):
    path = checkpoint_path(seed)
    checkpoint = load_checkpoint(path)
    theta = collect_theta(checkpoint["model_state_dict"])
    return quantize_theta_uniform(theta, B_THETA)


def load_quantized_attenu(seed):
    path = checkpoint_path(seed)
    checkpoint = load_checkpoint(path)
    attenu = collect_attenu(checkpoint["model_state_dict"])
    return quantize_attenu_uniform(attenu, B_ALPHA)


def load_forward_accuracy(seed):
    """Read the MNIST forward/test accuracy saved in the checkpoint."""
    path = checkpoint_path(seed)
    checkpoint = load_checkpoint(path)

    correct = checkpoint.get("correct")
    total = checkpoint.get("total")

    if correct is not None and total is not None and int(total) > 0:
        return float(correct) / float(total)

    test_acc = checkpoint.get("test_acc")
    if test_acc is None:
        raise KeyError(
            "The checkpoint contains neither valid 'correct'/'total' fields nor "
            f"a 'test_acc' field: {path.resolve()}"
        )

    return float(test_acc)


def plot_three_seed_theta_histogram(
    ax,
    theta_by_seed,
    forward_accuracy_by_seed,
):
    colors = NATURE_COLORS
    hatches = ["///", "\\\\", "xx"]

    # For 1-bit phase quantization, theta has only two possible levels (0 and pi).
    # Grouped bars keep the three seeds distinguishable even when their
    # distributions are nearly identical. Color, position, and hatch all encode
    # the seed so the figure remains readable in grayscale.
    quantization_levels_pi = np.array([0.0, 1.0])
    bar_width = 0.08
    offsets = np.array([-bar_width, 0.0, bar_width])

    for seed_index, (offset, color, hatch, (seed, theta)) in enumerate(
        zip(
            offsets,
            colors,
            hatches,
            theta_by_seed.items(),
        )
    ):
        theta_pi = np.mod(theta, THETA_PERIOD) / np.pi
        probabilities = np.array(
            [
                np.mean(np.isclose(theta_pi, level))
                for level in quantization_levels_pi
            ]
        )

        bars = ax.bar(
            quantization_levels_pi + offset,
            probabilities,
            width=bar_width,
            color=color,
            edgecolor="black",
            linewidth=1.2,
            hatch=hatch,
            label=(
                f"Seed {seed} "
                f"(infer acc: {forward_accuracy_by_seed[seed] * 100.0:.2f}%)"
            ),
            zorder=3,
        )

        for level_index, (bar, probability) in enumerate(zip(bars, probabilities)):
            bar_center = bar.get_x() + bar.get_width() / 2.0

            if level_index == 0:
                annotation_x = 0.32
                annotation_y_positions = [0.88, 0.74, 0.60]
                ax.annotate(
                    f"{probability:.2%}",
                    xy=(bar_center, probability),
                    xytext=(annotation_x, annotation_y_positions[seed_index]),
                    ha="left",
                    va="center",
                    fontsize=ANNOTATION_FONTSIZE,
                    color=color,
                    arrowprops={
                        "arrowstyle": "->",
                        "color": color,
                        "linewidth": 1.3,
                    },
                )
            else:
                label_y = min(probability + 0.015, 0.985)
                vertical_alignment = "bottom" if probability < 0.95 else "top"
                ax.text(
                    bar_center,
                    label_y,
                    f"{probability:.2%}",
                    ha="center",
                    va=vertical_alignment,
                    rotation=90,
                    fontsize=ANNOTATION_FONTSIZE,
                    color=color,
                    clip_on=True,
                )

    ax.set_title(
        r"(b) QAT-joint, ($b_\theta=1$, $b_a=1$) --- MNIST",
        fontsize=TITLE_FONTSIZE,
        fontweight="bold",
        pad=12,
    )
    ax.set_xlim(-0.35, 2.0)
    ax.set_xticks([0.0, 0.5, 1.0, 1.5, 2.0])
    ax.set_xticklabels(["0", r"$0.5\pi$", r"$\pi$", r"$1.5\pi$", r"$2\pi$"])
    ax.set_xlabel(r"$\theta_{ij}$", fontsize=AXIS_LABEL_FONTSIZE)
    ax.set_ylabel("Probability", fontsize=AXIS_LABEL_FONTSIZE)
    ax.set_ylim(0.0, 1.0)
    ax.tick_params(axis="both", which="major", labelsize=TICK_LABEL_FONTSIZE)
    ax.grid(True, axis="y", color="#B3B3B3", linewidth=0.8, alpha=0.45, zorder=0)
    ax.legend(frameon=True, fontsize=LEGEND_FONTSIZE, edgecolor="black")

def plot_three_seed_attenu_histogram(
    ax,
    attenu_by_seed,
    forward_accuracy_by_seed,
):
    colors = NATURE_COLORS
    hatches = ["///", "\\\\", "xx"]

    # For 1-bit attenuation quantization, a_ij has only two possible levels
    # (0 and 1). Use the same grouped-bar design as the theta figure.
    quantization_levels = np.array([0.0, 1.0])
    bar_width = 0.08
    offsets = np.array([-bar_width, 0.0, bar_width])

    for offset, color, hatch, (seed, attenu) in zip(
        offsets,
        colors,
        hatches,
        attenu_by_seed.items(),
    ):
        probabilities = np.array(
            [
                np.mean(np.isclose(attenu, level))
                for level in quantization_levels
            ]
        )

        bars = ax.bar(
            quantization_levels + offset,
            probabilities,
            width=bar_width,
            color=color,
            edgecolor="black",
            linewidth=1.2,
            hatch=hatch,
            label=(
                f"Seed {seed} "
                f"(infer acc: {forward_accuracy_by_seed[seed] * 100.0:.2f}%)"
            ),
            zorder=3,
        )

        for bar, probability in zip(bars, probabilities):
            label_y = min(probability + 0.015, 0.985)
            vertical_alignment = "bottom" if probability < 0.95 else "top"
            ax.text(
                bar.get_x() + bar.get_width() / 2.0,
                label_y,
                f"{probability:.2%}",
                ha="center",
                va=vertical_alignment,
                rotation=90,
                fontsize=ANNOTATION_FONTSIZE,
                color=color,
                clip_on=True,
            )

    ax.set_title(
        r"(a) QAT-joint, ($b_\theta=1$, $b_a=1$) --- MNIST",
        fontsize=TITLE_FONTSIZE,
        fontweight="bold",
        pad=12,
    )
    ax.set_xlim(-0.175, 1.175)
    ax.set_xticks([0.0, 0.25, 0.5, 0.75, 1.0])
    ax.set_xticklabels(["0", "0.25", "0.5", "0.75", "1"])
    ax.set_xlabel(r"$a_{ij}$", fontsize=AXIS_LABEL_FONTSIZE)
    ax.set_ylabel("Probability", fontsize=AXIS_LABEL_FONTSIZE)
    ax.set_ylim(0.0, 1.0)
    ax.tick_params(axis="both", which="major", labelsize=TICK_LABEL_FONTSIZE)
    ax.grid(True, axis="y", color="#B3B3B3", linewidth=0.8, alpha=0.45, zorder=0)
    ax.legend(
        loc="upper left",
        frameon=True,
        fontsize=LEGEND_FONTSIZE,
        edgecolor="black",
    )

def save_combined_distribution_figure(
    theta_by_seed,
    attenu_by_seed,
    forward_accuracy_by_seed,
    save_path,
):
    fig, axes = plt.subplots(1, 2, figsize=(10.8, 4.6))

    # Required panel order: attenuation on the left and phase on the right.
    plot_three_seed_attenu_histogram(
        axes[0],
        attenu_by_seed,
        forward_accuracy_by_seed,
    )
    plot_three_seed_theta_histogram(
        axes[1],
        theta_by_seed,
        forward_accuracy_by_seed,
    )

    save_path.parent.mkdir(parents=True, exist_ok=True)
    fig.tight_layout(w_pad=2.5)
    fig.savefig(save_path, dpi=300, bbox_inches="tight")
    plt.close(fig)


def main():
    theta_by_seed = {
        seed: load_quantized_theta(seed)
        for seed in SEEDS
    }
    attenu_by_seed = {
        seed: load_quantized_attenu(seed)
        for seed in SEEDS
    }
    forward_accuracy_by_seed = {
        seed: load_forward_accuracy(seed)
        for seed in SEEDS
    }

    save_combined_distribution_figure(
        theta_by_seed,
        attenu_by_seed,
        forward_accuracy_by_seed,
        COMBINED_OUTPUT_PATH,
    )

    print("\nMNIST forward test accuracy:")
    for seed, accuracy in forward_accuracy_by_seed.items():
        print(f"  Seed {seed}: {accuracy:.4f} ({accuracy * 100.0:.2f}%)")

    accuracy_values = np.asarray(
        list(forward_accuracy_by_seed.values()),
        dtype=np.float64,
    )
    mean_accuracy = float(np.mean(accuracy_values))
    sample_std_accuracy = float(np.std(accuracy_values, ddof=1))
    print(
        "  Three-seed mean +/- sample std: "
        f"{mean_accuracy * 100.0:.2f}% +/- {sample_std_accuracy * 100.0:.2f}%"
    )

    print(
        "Generated combined MNIST QAT-joint attenuation and theta distribution "
        f"for seeds {SEEDS}: {COMBINED_OUTPUT_PATH.resolve()}"
    )


if __name__ == "__main__":
    main()


